'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { execFileSync, spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { manualClock } = require('../src/clock');
const { loadConfig } = require('../src/config');
const { silentLogger } = require('../src/log');
const { createPersistence } = require('../src/persistence');
const { createService } = require('../src/server');
const { TicketStore } = require('../src/store');
const { formatId } = require('../src/tickets/ids');
const { ticketBody, withService } = require('./helpers');

const CREATED = '2025-09-01T08:15:00.000Z';
const HOUR_MS = 3_600_000;

function dataFileFor(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'tickets-due-'));
  t.after(() => fs.rmSync(dir, { recursive: true }));
  return path.join(dir, 'tickets.json');
}

function settings(dataFile, env = {}) {
  return loadConfig({ PORT: '0', WORKER_INTERVAL_MS: '0', DATA_FILE: dataFile, DUE_TIMES: 'on', ...env });
}

function readFile(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function seedLegacy(file, clock) {
  const store = TicketStore.open({ clock, persistence: createPersistence(file, { clock }) });
  for (const priority of ['high', 'urgent', 'normal', 'low']) store.create(ticketBody({ priority }), 'desk');
  store.recordDelivery(1);
  for (let attempt = 0; attempt < 5; attempt += 1) store.recordDelivery(2, new Error('mail relay unavailable'));
  clock.advance(HOUR_MS);
  store.update('T-0001', { title: 'Printer still jams' }, 'agent');
  store.transition('T-0002', 'in_progress', 'agent');
  for (const id of ['T-0003', 'T-0004']) {
    for (const status of ['in_progress', 'resolved']) store.transition(id, status, 'agent');
  }
  store.transition('T-0004', 'closed', 'agent');
}

test('startup prepares every legacy status before serving and preserves tickets, audit and outbox', async (t) => {
  const dataFile = dataFileFor(t);
  const clock = manualClock(CREATED);
  seedLegacy(dataFile, clock);
  const before = readFile(dataFile);
  const deadlines = [
    '2025-09-02T08:15:00.000Z', '2025-09-01T12:15:00.000Z',
    '2025-09-04T08:15:00.000Z', '2025-09-08T08:15:00.000Z',
  ];

  await withService({ ...settings(dataFile), clock }, async (api) => {
    const prepared = readFile(dataFile);
    assert.equal(prepared.version, 1);
    assert.equal(prepared.nextNumber, before.nextNumber);
    assert.deepEqual(prepared.tickets, before.tickets.map((ticket, index) => ({ ...ticket, due: deadlines[index] })));
    assert.deepEqual(prepared.audit, before.audit);
    assert.deepEqual(prepared.outbox, before.outbox);
    const { status, body } = await api.get('/tickets');
    assert.equal(status, 200);
    assert.deepEqual(body.items, prepared.tickets);
    assert.deepEqual((await api.get('/tickets/T-0003/audit')).body.items, before.audit.filter((entry) => entry.ticket === 'T-0003'));

    const created = await api.post('/tickets', ticketBody({ priority: 'urgent' }));
    assert.equal(created.status, 201);
    assert.equal(created.body.id, 'T-0005');
    assert.equal(created.body.due, '2025-09-01T13:15:00.000Z');
    const saved = readFile(dataFile);
    assert.deepEqual(saved.tickets.at(-1), created.body);
    assert.equal(saved.audit.at(-1).seq, before.audit.length + 1);
    assert.equal(saved.audit.at(-1).changes.priority.to, 'urgent');
    assert.equal(saved.outbox.events.at(-1).id, before.outbox.nextId);
    assert.equal(saved.outbox.events.at(-1).key, 'ticket.created:T-0005');
    for (const to of ['in_progress', 'resolved', 'open', 'in_progress', 'resolved']) {
      assert.equal((await api.post('/tickets/T-0005/transition', { to })).status, 200);
    }
    const { pending } = (await api.get('/admin/outbox')).body;
    assert.equal(pending.filter((event) => event.key === 'ticket.resolved:T-0005').length, 1);
  });

  await withService({ ...settings(dataFile, { DUE_HOURS_URGENT: '6' }), clock }, async (api) => {
    assert.equal((await api.get('/tickets/T-0002')).body.due, deadlines[1]);
    assert.equal((await api.patch('/tickets/T-0002', { priority: 'low' })).body.due, deadlines[1]);
    assert.equal((await api.get('/tickets/T-0005')).body.due, '2025-09-01T13:15:00.000Z');
    assert.equal((await api.post('/tickets', ticketBody({ priority: 'urgent' }))).body.due, '2025-09-01T15:15:00.000Z');
  });
});

test('off mode ignores overdue and keeps stored deadlines through request, worker and shutdown saves', async (t) => {
  const dataFile = dataFileFor(t);
  const clock = manualClock(CREATED);
  seedLegacy(dataFile, clock);
  const baseline = readFile(dataFile);
  let prepared;
  await withService({ ...settings(dataFile), clock }, async () => {
    prepared = readFile(dataFile).tickets;
  });
  const assertSaved = () => assert.deepEqual(readFile(dataFile).tickets.slice(0, 4).map((ticket) => ticket.due),
    prepared.map((ticket) => ticket.due));

  for (const flag of [undefined, '', 'ON', ' on ']) {
    await withService({ ...settings(dataFile, { DUE_TIMES: flag }), clock }, async (api) => {
      const ordinary = await api.get('/tickets');
      assert.equal(ordinary.status, 200);
      assert.deepEqual(ordinary.body, { items: baseline.tickets, next: null });
      for (const query of ['overdue=true', 'overdue=', 'overdue=no&overdue=true']) {
        assert.deepEqual((await api.get(`/tickets?${query}`)).body, ordinary.body);
      }
      assert.deepEqual((await api.get('/tickets/T-0002')).body, baseline.tickets[1]);
      assert.equal((await api.get('/tickets?overdue=true&limit=0')).status, 400);
    });
    assertSaved();
  }

  await withService({ ...settings(dataFile, { DUE_TIMES: '' }), clock }, async (api, service) => {
    for (const response of [
      await api.patch('/tickets/T-0001', { title: 'Revised title' }),
      await api.patch('/tickets/T-0001', { title: 'Revised title' }),
      await api.post('/tickets/T-0001/transition', { to: 'in_progress' }),
    ]) {
      assert.equal(response.status, 200);
      assert.equal(Object.hasOwn(response.body, 'due'), false);
    }
    assertSaved();
    const newTicket = await api.post('/tickets', ticketBody({ priority: 'urgent' }));
    assert.equal(newTicket.status, 201);
    assert.equal(Object.hasOwn(newTicket.body, 'due'), false);
    assertSaved();
    const sentBefore = readFile(dataFile).outbox.events.filter((event) => event.status === 'sent').length;
    service.worker.tick();
    assert.ok(readFile(dataFile).outbox.events.filter((event) => event.status === 'sent').length > sentBefore);
    assertSaved();
  });
  assertSaved();
  await withService({ ...settings(dataFile, { DUE_HOURS_URGENT: '6' }), clock }, async (api) => {
    assert.equal((await api.get('/tickets/T-0002')).body.due, prepared[1].due);
    assert.equal((await api.get('/tickets/T-0005')).body.due, '2025-09-01T15:15:00.000Z');
  });
});

test('a failed preparation leaves the mixed file intact and retry assigns only missing deadlines', async (t) => {
  const dataFile = dataFileFor(t);
  const clock = manualClock(CREATED);
  seedLegacy(dataFile, clock);
  const disk = createPersistence(dataFile, { clock });
  const state = disk.load();
  state.tickets[1].due = '2025-09-01T12:15:00.000Z';
  disk.save(state);
  const retained = fs.readFileSync(dataFile, 'utf8');
  const blocked = `${dataFile}.${process.pid}.tmp`;
  const config = settings(dataFile, { DUE_HOURS_URGENT: '6' });
  fs.mkdirSync(blocked);
  try {
    assert.throws(() => createService(config, { clock, log: silentLogger }), { name: 'DataFileError' });
    assert.equal(fs.readFileSync(dataFile, 'utf8'), retained);
  } finally {
    fs.rmdirSync(blocked);
  }
  await withService({ ...config, clock }, async (api) => {
    assert.equal((await api.get('/tickets/T-0001')).body.due, '2025-09-02T08:15:00.000Z');
    assert.equal((await api.get('/tickets/T-0002')).body.due, state.tickets[1].due);
    assert.equal(readFile(dataFile).tickets[1].due, state.tickets[1].due);
  });
});

